from pathlib import Path
import base64
root=Path(__file__).resolve().parents[1]
video=root/'renders/mystery-button-compatible.mp4'
data=base64.b64encode(video.read_bytes()).decode()
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bobo & Max — Video preview</title><style>body{margin:0;background:#101c2c;color:#e9f2ed;font:16px Arial,sans-serif}main{max-width:1000px;margin:auto;padding:24px}h1{font-size:27px;margin-bottom:8px}p{color:#abc0cb;line-height:1.6}video{display:block;margin:24px auto;width:min(100%,430px);max-height:80vh;background:#000;border-radius:12px}button,a{display:inline-block;background:#d7e9ad;color:#17261c;border:0;border-radius:6px;padding:12px 18px;text-decoration:none;font:inherit;cursor:pointer;margin:6px}nav{text-align:center}.note{font-size:12px}button:focus-visible,a:focus-visible{outline:3px solid white}</style></head><body><main><h1>Bobo & Max: The Mystery Button</h1><p>The complete original animation. 1080 × 1920 · 30 fps · H.264 Main · AAC audio.</p><video id="film" controls playsinline preload="metadata" src="data:video/mp4;base64,VIDEO"></video><nav><button data-time="0">Start</button><button data-time="30">Portal</button><button data-time="55">Banana Max</button><button data-time="65">The question</button><a id="download" download="mystery-button-compatible.mp4">Download MP4</a></nav><p class="note">Self-contained preview: download this HTML and open it in Chrome. No Internet connection is needed. Press Play to enable sound. If the Codex viewer does not display the file, use its download action and open it locally.</p></main><script>const v=document.getElementById('film');document.getElementById('download').href=v.src;document.querySelectorAll('button').forEach(b=>b.onclick=()=>{v.currentTime=Number(b.dataset.time);v.play();});</script></body></html>'''.replace('VIDEO',data)
preview=root/'renders/video-preview.html';preview.write_text(page)
for file in [video,preview]:file.chmod(0o644);print(file.name,file.stat().st_size)
